#!/usr/bin/env python3
"""Refresh the local Font Awesome solid subset used by the dashboard.

Downloads SVGs from jsDelivr (@fortawesome/fontawesome-free) into
vendor/fontawesome/svgs/solid/ and regenerates icons.json / icons.js / icons.mjs.

Run from the repository root or this directory:

    python3 dashboard/frontend/vendor/fontawesome/sync.py
"""
from __future__ import annotations

import json
import re
import urllib.request
from pathlib import Path

ROOT = Path(__file__).resolve().parent
VERSION = "6.7.2"
STYLE = "solid"
ICONS = [
    "align-left", "arrows-rotate", "bars", "check", "chevron-down", "chevron-left",
    "chevron-right", "chevron-up", "circle", "circle-half-stroke", "cloud",
    "code", "download", "ellipsis", "eye", "file", "file-circle-plus",
    "file-code", "file-lines", "file-pdf", "floppy-disk", "gear", "folder",
    "folder-open", "folder-plus", "folder-tree", "hourglass-half", "lock",
    "magnifying-glass", "minus", "moon", "play", "plus", "sort-down",
    "sort-up", "sun", "xmark",
]


def main() -> int:
    out = ROOT / "svgs" / STYLE
    out.mkdir(parents=True, exist_ok=True)
    base = f"https://cdn.jsdelivr.net/npm/@fortawesome/fontawesome-free@{VERSION}/svgs/{STYLE}/{{}}.svg"
    manifest = {"version": VERSION, "style": STYLE, "icons": {}}
    for name in ICONS:
        url = base.format(name)
        with urllib.request.urlopen(url, timeout=30) as response:
            text = response.read().decode("utf-8")
        (out / f"{name}.svg").write_text(text, encoding="utf-8")
        path = re.search(r'<path[^>]*\sd="([^"]+)"', text)
        viewbox = re.search(r'viewBox="([^"]+)"', text)
        if not path or not viewbox:
            raise SystemExit(f"could not parse {name}")
        manifest["icons"][name] = {"viewBox": viewbox.group(1), "path": path.group(1)}
        print("ok", name)

    (ROOT / "icons.json").write_text(json.dumps(manifest, indent=2) + "\n", encoding="utf-8")
    icons = manifest["icons"]
    (ROOT / "icons.mjs").write_text(
        "/** Local Font Awesome solid icon collection (subset). Auto-generated by sync.py */\n"
        f"export const FA_VERSION = {VERSION!r};\n"
        f"export const FA_STYLE = {STYLE!r};\n"
        f"export const FA_ICONS = {json.dumps(icons, indent=2)};\n\n"
        "export function faSvg(name, className = \"\") {\n"
        "  const icon = FA_ICONS[name];\n"
        "  if (!icon) return null;\n"
        "  const svg = document.createElementNS(\"http://www.w3.org/2000/svg\", \"svg\");\n"
        "  svg.setAttribute(\"viewBox\", icon.viewBox);\n"
        "  svg.setAttribute(\"aria-hidden\", \"true\");\n"
        "  svg.setAttribute(\"focusable\", \"false\");\n"
        "  if (className) svg.setAttribute(\"class\", className);\n"
        "  const path = document.createElementNS(\"http://www.w3.org/2000/svg\", \"path\");\n"
        "  path.setAttribute(\"fill\", \"currentColor\");\n"
        "  path.setAttribute(\"d\", icon.path);\n"
        "  svg.append(path);\n"
        "  return svg;\n"
        "}\n\n"
        "export function faHtml(name, className = \"app-icon\") {\n"
        "  const icon = FA_ICONS[name];\n"
        "  if (!icon) return \"\";\n"
        "  const cls = className ? ` class=\"${className}\"` : \"\";\n"
        "  return `<svg${cls} viewBox=\"${icon.viewBox}\" aria-hidden=\"true\" focusable=\"false\">"
        "<path fill=\"currentColor\" d=\"${icon.path}\"/></svg>`;\n"
        "}\n",
        encoding="utf-8",
    )
    (ROOT / "icons.js").write_text(
        "/** Local Font Awesome solid icon collection (subset). Auto-generated by sync.py */\n"
        f"window.FA_ICONS = {json.dumps(icons)};\n"
        f"window.FA_VERSION = {VERSION!r};\n"
        "window.faHtml = function(name, className) {\n"
        "  const icon = window.FA_ICONS[name];\n"
        "  if (!icon) return \"\";\n"
        "  const cls = className ? (' class=\"' + className + '\"') : \"\";\n"
        "  return '<svg' + cls + ' viewBox=\"' + icon.viewBox + '\" aria-hidden=\"true\" focusable=\"false\">"
        "<path fill=\"currentColor\" d=\"' + icon.path + '\"/></svg>';\n"
        "};\n",
        encoding="utf-8",
    )
    print(f"wrote {len(icons)} icons @ {VERSION}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
